//   iconXxxStatus        -> 10  x 10  (status bar)   = 100   entries
//
// Once populated, set ICONS_HAVE_DATA to 1 in Config.h to enable the
// real pixel blit in UI.cpp (drawBitmapIcon).
// =====================================================================

